                <a href="{{ cgUrl }}" target="_blank" style="text-decoration:none; padding:5px 12px; border-radius:8px; border:1px solid rgba(151,252,228,.18); background:transparent; color:#9CB8AF; font-family:'JetBrains Mono'; font-size:10.5px; font-weight:600; letter-spacing:.06em;">LOG IN / OPEN ↗</a>
